/// <summary>
/// MPJ_28152_CSD_Fulfilment 3.6.2.1 Calculate Qty not reserved
/// </summary>
class METQtyNotReservedCalculateController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
    /// <summary>Constuct new object</summary>
    /// <param name = "_args">Arguments</param>
    /// <param name = "_executionMode">Execution mode</param>
    /// <returns>New Controller Object</returns>
    public static METQtyNotReservedCalculateController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
    {
        METQtyNotReservedCalculateController controller = new METQtyNotReservedCalculateController();
        controller.parmExecutionMode(_executionMode);
        controller.parmArgs(_args);
        controller.parmLoadFromSysLastValue(false);

        return controller;
    }

/// <summary>
/// New method specifying the service class method to call
/// </summary>
protected void new()
{
    super(classstr(METQtyNotReservedCalculateService), methodstr(METQtyNotReservedCalculateService, run), SysOperationExecutionMode::Synchronous);
}

    /// <summary>
    /// Create the RecordSortedList from selected records in open sales order line form
    /// </summary>
    /// <param name = "_formDataSource">Form <c>SalesLineOpenOrder</c> SalesLine datasource</param>
    /// <returns>RecordSortedList of <c>SalesLine</c> records selected in the form</returns>
    static RecordSortedList createRecordSortedList(FormDataSource _formDataSource)
    {
        RecordSortedList        salesLineSelected;
        SalesLine               salesLine;
        MultiSelectionHelper    selection;

        salesLineSelected = new RecordSortedList(tableNum(SalesLine));
        selection = MultiSelectionHelper::construct();
        selection.parmDatasource(_formDataSource);
        salesLine = selection.getFirst();

        salesLineSelected.sortOrder(fieldnum(SalesLine, InventTransId));

        // insert selected records in a recordSortedList sorted by route and route stops ascending
        while (salesLine)
        {
            salesLineSelected.ins(salesLine);

            salesLine = selection.getNext();
        }

        return salesLineSelected;
    }

    /// <summary>
    /// Main method
    /// </summary>
    /// <param name = "_args">Arguments</param>
    public static void main(Args _args)
    {
        METQtyNotReservedCalculateController    controller;
        METQtyNotReservedCalculateContract      contract;
        FormDataSource                          formDS;
        TableId                                 callerTableId;
        FormRun                                 callingFormRun;

        if (!_args.caller())
        {
            throw error("@SYS22539");
        }

        callingFormRun = _args.caller() as FormRun;

        if (_args && callingFormRun)
        {
            callerTableId = _args.dataset();
            switch (callerTableId)
            {
                case tableNum(SalesLine):
                    // get the caller datasource
                    formDS = FormDataUtil::getFormDataSource(_args.record());
                    break;
            }

            // create controller
            controller = METQtyNotReservedCalculateController::construct(_args);
            
            // get contract object
            contract = controller.getDataContractObject();

            // set selected salesLine RecordSortedList in the contract
            contract.parmSelectedSalesLine(METQtyNotReservedCalculateController::createRecordSortedList(formDS));

            // don't show any dialog
            controller.parmShowDialog(false);

            // execute the service class
            controller.startOperation();

            // Refresh records from the open sales order line form            
            formDS.research(true);

        }
    }

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}
